+}
+
+// ExportXML writes the book's levels as XML to w.
+// The root element is <Levels> containing <Level> elements.
+func (b *Book) ExportXML(w interface{ Write([]byte) (int, error) }) error {
+	type XMLLevels struct {
+		XMLName xml.Name `xml:"Levels"`
+		Levels  []Level  `xml:"Level"`
+	}
+	return xml.NewEncoder(w).Encode(XMLLevels{Levels: b.Levels()})
+}
+
+func itoa(n int) string {
+	if n == 0 {
+		return "0"
+	}
+	neg := n < 0
+	if neg {
+		n = -n
+	}
+	var b [20]byte
+	i := len(b)
+	for n > 0 {
+		i--
+		b[i] = byte('0' + n%10)
+		n /= 10
+	}
+	if neg {
+		i--
+		b[i] = '-'
+	}
+	return string(b[i:])
+}

